//! 🧪️ Constructor children keep original words and born owners through denied and cancelled turns.
use super::*;
use semio_framework_plugin::app_testing::OriginalWorkFixture;
fn source()->DslValue{DslValue::Object(vec![("name".into(),DslValue::String("IFCLENGTHMEASURE".into())),("items".into(),DslValue::Array(vec![DslValue::Object(vec![("kind".into(),DslValue::String("real".into())),("value".into(),DslValue::Object(vec![("bits".into(),DslValue::String("a".repeat(63)+"€"+&"ä".repeat(40)))]))])]))])}
fn retire<T:RetireOwned>(caller:&mut OriginalWorkFixture,owner:&mut Option<T>){let mut close=RetainedCloneClose::default();for turn in 0..100000{if owner.is_none()&&close.is_empty(){break;}let demand=close.next_owner_demands::<T>(owner.is_some(),&None,4096).unwrap();caller.turn(OriginalWorkFixture::stock(),|cx|cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,demand,|grant|if close.is_empty(){close.begin_granted(owner,grant)?.ok_or_else(invalid)}else{close.step_granted(grant)})?;Ok(())})).unwrap();assert!(turn<99999);}assert!(owner.is_none()&&close.is_empty());}
#[test]
fn original_constructor_copy_preserves_only_compatible_children_and_all_denied_axes(){let source=source();for(name,kind,fill,count)in[("IFCPARAMETERVALUE",InputKind::Real,false,1),("IFCDURATION",InputKind::String,false,0),("IFCDURATION",InputKind::String,true,1)]{let input=Input{source:Some(&source),name,kind,fill};let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());let mut output=None;for turn in 0..100000{let demand=copy.as_ref().unwrap().demands(&input).unwrap();for axis in 0..6{let mut denied=OriginalWorkFixture::stock();let mut fuel=1;match axis{0=>denied.maximum_items=0,1 if demand.copy_bytes>0=>denied.maximum_copy_bytes=demand.copy_bytes-1,2 if demand.capacity_bytes>0=>denied.maximum_capacity_bytes=demand.capacity_bytes-1,3 if demand.release_bytes>0=>denied.maximum_release_bytes=demand.release_bytes-1,4=>denied.maximum_depth=demand.depth-1,5=>fuel=0,_=>continue};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(denied,fuel,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&input,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(!answer.unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){break;}assert!(turn<99999);}assert!(caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().take(&mut output,cx)).unwrap());let(tag,items)=super::super::super::type_input::typed_constructor(output.as_ref().unwrap()).unwrap();assert_eq!(tag,name);assert_eq!(items.len(),count);if kind==InputKind::Real{assert_eq!(output.as_ref().unwrap().get("items"),source.get("items"));}else if fill{assert_eq!(items[0].get("value").and_then(DslValue::as_str),Some(""));}retire(&mut caller,&mut copy);retire(&mut caller,&mut output);caller.finish();}}
#[test]
fn original_constructor_copy_keeps_cancelled_prefixes_retirable(){let source=source();let input=Input{source:Some(&source),name:"IFCPARAMETERVALUE",kind:InputKind::Real,fill:false};let mut total=None;for prefix in std::iter::once(None).chain((0..100000).map(Some)){if prefix.is_some_and(|prefix|total.is_some_and(|total|prefix>=total)){break;}let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());for turn in 0..100000{if prefix==Some(turn){caller.cancel().cancel_now();let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&input,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));break;}if caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap(){total=Some(turn+1);assert!(prefix.is_none());break;}assert!(turn<99999);}retire(&mut caller,&mut copy);caller.finish();}assert!(total.is_some());}
#[test]
fn original_constructor_copy_refuses_source_target_and_caller_replacement(){let source=source();let substitute=source.clone();let input=Input{source:Some(&source),name:"IFCPARAMETERVALUE",kind:InputKind::Real,fill:false};let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());assert!(!caller.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).unwrap());for replacement in [Input{source:Some(&substitute),..input},Input{name:"IFCLENGTHMEASURE",..input},Input{fill:true,..input}]{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|{let before=cx.retained_progress();let answer=copy.as_mut().unwrap().advance(&replacement,cx);assert_eq!(before,cx.retained_progress());answer}));assert!(answer.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}let mut foreign=OriginalWorkFixture::with_identity(semio_framework_job::OperationId(991),semio_framework_job::Generation(2));assert!(foreign.work_turn(OriginalWorkFixture::stock(),1,|cx|copy.as_mut().unwrap().advance(&input,cx)).is_err());foreign.finish();retire(&mut caller,&mut copy);caller.finish();}
#[test]
fn original_constructor_string_stays_retained_on_refused_receipt_posting(){let mut caller=OriginalWorkFixture::new();let mut copy=Some(TypedCopy::default());*copy.as_mut().unwrap().parts=Some(Parts{strings:Default::default(),root:None,items:None,child:None,bits:None,aggregate_value:None,output:None});let physical=OriginalConstructionDemand{items:1,copy_bytes:4096,capacity_bytes:19,release_bytes:0,depth:4};let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||caller.work_turn(OriginalWorkFixture::stock(),1,|cx|construct_row_string(&mut copy.as_mut().unwrap().parts.as_mut().unwrap().strings[7],20,"original typed draft",physical,cx)));assert!(answer.is_err());assert_eq!(copy.as_ref().unwrap().parts.as_ref().unwrap().strings[7].as_deref(),Some("original typed draft"));assert!(heap.requested_bytes>=20);assert_eq!(heap.released_bytes,0);retire(&mut caller,&mut copy);caller.finish();}
